public class DiscountResolver {
    private final Map<String, BigDecimal> cache = new ConcurrentHashMap<>();
    private final CategoryRepository categories;

    public DiscountResolver(CategoryRepository categories) {
        this.categories = categories;
    }

    public BigDecimal discountOf(String categoryId) {
        return cache.computeIfAbsent(categoryId, id -> {
            Category category = categories.find(id);
            if (category.discount() != null) return category.discount();
            return discountOf(category.parentId());   // kế thừa từ category cha
        });
    }
}

fix.code:
public BigDecimal discountOf(String categoryId) {
    BigDecimal cached = cache.get(categoryId);
    if (cached != null) return cached;

    Category category = categories.find(categoryId);
    BigDecimal discount = category.discount() != null
            ? category.discount()
            : discountOf(category.parentId());   // đệ quy ngoài map

    BigDecimal existing = cache.putIfAbsent(categoryId, discount);
    return existing != null ? existing : discount;
}
